1	"use client";
2	
3	import Link from "next/link";
4	import { usePathname } from "next/navigation";
5	import { useEffect, useRef, useState } from "react";
6	import { NxLogo } from "./Logo";
7	import { ClaudeMark } from "./ClaudeMark";
8	import {
9	  IconServer,
10	  IconGame,
11	  IconSpark,
12	  IconDisk,
13	  IconNetwork,
14	  IconGlobe,
15	  IconMail,
16	  IconCode,
17	  IconApps,
18	  IconArrow,
19	  IconBeaker,
20	} from "./icons";
21	
22	/**
23	 * Marketing top nav (v2 redesign). A grouped structure instead of a flat link
24	 * list: a Products mega-menu organized by outcome (Compute / Storage & Network /
25	 * Web Essentials) plus a "by use case" rail, then Pricing · Compare · Blog and a
26	 * Company dropdown. One prominent primary CTA; a live Status pill on the right.
27	 */
28	
29	type Item = { label: string; href: string; desc: string; icon: (p: { size?: number }) => React.ReactNode; badge?: string };
30	
31	const PRODUCT_GROUPS: { title: string; items: Item[] }[] = [
32	  {
33	    title: "Compute",
34	    items: [
35	      { label: "VPS Hosting", href: "/vps", desc: "Full-root NVMe KVM servers", icon: IconServer },
36	      { label: "Game Servers", href: "/game-servers", desc: "Minecraft, Rust, Valheim & more", icon: IconGame },
37	      { label: "Claude AI Builder", href: "/features", desc: "Build your server in plain English", icon: ClaudeMark, badge: "New" },
38	      { label: "Matrix", href: "/matrix", desc: "Build several apps at once with AI", icon: IconApps, badge: "New" },
39	    ],
40	  },
41	  {
42	    title: "Storage & Network",
43	    items: [
44	      { label: "Block Storage", href: "/block-storage", desc: "Add-on NVMe volumes", icon: IconDisk },
45	      { label: "NxCloud", href: "/nxcloud", desc: "Your own managed Nextcloud", icon: IconDisk, badge: "New" },
46	      { label: "Dedicated IPv4", href: "/vps", desc: "A clean, static IP per server", icon: IconNetwork },
47	    ],
48	  },
49	  {
50	    title: "Web Essentials",
51	    items: [
52	      { label: "Web Hosting", href: "/web-hosting", desc: "One-click WordPress & sites", icon: IconApps, badge: "New" },
53	      { label: "Domains", href: "/domains", desc: "Register & manage domains", icon: IconGlobe },
54	      { label: "Business Email", href: "/business-email", desc: "Mailboxes on your own domain", icon: IconMail },
55	    ],
56	  },
57	];
58	
59	const USE_CASES: Item[] = [
60	  { label: "Vibe coding", href: "/vibe-coding", desc: "Build sites & apps, no code", icon: IconSpark, badge: "New" },
61	  { label: "Free tools", href: "/tools", desc: "WHOIS, DNS, SSL & more", icon: IconNetwork, badge: "Free" },
62	  { label: "Migrate to Nxeon", href: "/migrate", desc: "Free — bring your servers", icon: IconArrow },
63	  { label: "Developers & API", href: "/developers", desc: "Automate everything", icon: IconCode },
64	  { label: "AI apps & agents", href: "/features", desc: "Ship agents in minutes", icon: IconSpark },
65	];
66	
67	const COMPANY: { label: string; href: string }[] = [
68	  { label: "About", href: "/about" },
69	  { label: "Blog", href: "/blog" },
70	  { label: "Security", href: "/security" },
71	  { label: "Contact", href: "/contact" },
72	  { label: "Affiliate program", href: "/affiliate" },
73	  { label: "Status", href: "/status" },
74	];
75	
76	export function MarketingHeader() {
77	  const pathname = usePathname();
78	  const [open, setOpen] = useState(false); // mobile drawer
79	  const [menu, setMenu] = useState<null | "products" | "company">(null); // desktop dropdown
80	  const [scrolled, setScrolled] = useState(false);
81	  const [authed, setAuthed] = useState(false);
82	  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
83	
84	  // Show "Back to portal" for a signed-in visitor while keeping marketing pages
85	  // static. Two-step, after mount: (1) optimistic read of the non-httpOnly
86	  // `nxeon_authed` flag cookie (instant, no flash when present), then (2) an
87	  // authoritative probe to /api/auth/status which reads the real session cookie
88	  // server-side — so it's correct even if the flag cookie is missing or stale.
89	  useEffect(() => {
90	    setAuthed(document.cookie.split("; ").some((c) => c.startsWith("nxeon_authed=")));
91	    let alive = true;
92	    fetch("/api/auth/status", { cache: "no-store" })
93	      .then((r) => (r.ok ? r.json() : null))
94	      .then((d) => {
95	        if (alive && d && typeof d.authed === "boolean") setAuthed(d.authed);
96	      })
97	      .catch(() => {});
98	    return () => {
99	      alive = false;
100	    };
101	  }, []);
102	
103	  useEffect(() => {
104	    const onScroll = () => setScrolled(window.scrollY > 8);
105	    onScroll();
106	    window.addEventListener("scroll", onScroll, { passive: true });
107	    return () => window.removeEventListener("scroll", onScroll);
108	  }, []);
109	
110	  useEffect(() => {
111	    setOpen(false);
112	    setMenu(null);
113	  }, [pathname]);
114	
115	  // Hover-intent: brief close delay so diagonal mouse travel to the panel doesn't drop it.
116	  const openMenu = (m: "products" | "company") => {
117	    if (closeTimer.current) clearTimeout(closeTimer.current);
118	    setMenu(m);
119	  };
120	  const scheduleClose = () => {
121	    if (closeTimer.current) clearTimeout(closeTimer.current);
122	    closeTimer.current = setTimeout(() => setMenu(null), 120);
123	  };
124	
125	  return (
126	    <header
127	      className={`sticky top-0 z-50 border-b transition-colors duration-300 ${
128	        scrolled || menu ? "border-white/[0.06] bg-navy-950/85 backdrop-blur-xl" : "border-transparent bg-transparent"
129	      }`}
130	      onMouseLeave={scheduleClose}
131	    >
132	      <div className="rail flex h-[72px] items-center justify-between">
133	        {/* NxLogo renders its own home Link + aria-label — do NOT wrap it in a
134	            second Link (that produced a nested-<a> hydration error site-wide). */}
135	        <div className="shrink-0">
136	          <NxLogo id="hdr" size={44} />
137	        </div>
138	
139	        {/* Desktop nav */}
140	        <nav className="hidden items-center gap-1 lg:flex">
141	          <button
142	            className={`nav-trigger nav-underline ${menu === "products" ? "is-open" : ""}`}
143	            onMouseEnter={() => openMenu("products")}
144	            onFocus={() => openMenu("products")}
145	            aria-expanded={menu === "products"}
146	          >
147	            Products <Chevron open={menu === "products"} />
148	          </button>
149	          <TopLink href="/matrix" pathname={pathname}>Matrix</TopLink>
150	          <TopLink href="/pricing" pathname={pathname}>Pricing</TopLink>
151	          <TopLink href="/compare" pathname={pathname}>Compare</TopLink>
152	          <Link
153	            href="/mods"
154	            className={`nav-underline flex flex-col items-center gap-0.5 rounded-lg px-3 py-1.5 text-sm font-medium transition-colors ${
155	              pathname === "/mods" ? "is-open text-white" : "text-slate-400 hover:text-white"
156	            }`}
157	          >
158	            <span className="flex items-center gap-1.5">
159	              <IconBeaker size={15} />
160	              NxLabs
161	            </span>
162	            <span className="rounded-full bg-brand-500/20 px-1.5 py-0.5 text-[10px] font-semibold leading-none text-brand-200">
163	              Game Mod Store
164	            </span>
165	          </Link>
166	          <div className="relative" onMouseEnter={() => openMenu("company")} onMouseLeave={scheduleClose}>
167	            <button
168	              className={`nav-trigger nav-underline ${menu === "company" ? "is-open" : ""}`}
169	              onFocus={() => openMenu("company")}
170	              aria-expanded={menu === "company"}
171	            >
172	              Company <Chevron open={menu === "company"} />
173	            </button>
174	
175	            {/* Company dropdown — anchored directly beneath its trigger */}
176	            {menu === "company" && (
177	              <div className="absolute left-0 top-full hidden pt-3 lg:block">
178	                <div className="w-56 rounded-2xl border border-white/10 bg-navy-950/95 p-2 shadow-2xl backdrop-blur-2xl">
179	                  {COMPANY.map((l) => (
180	                    <Link key={l.href} href={l.href} className="flex items-center justify-between rounded-lg px-3 py-2 text-sm text-slate-300 hover:bg-white/[0.05] hover:text-white">
181	                      {l.label}
182	                      {l.label === "Status" && <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse-dot" />}
183	                    </Link>
184	                  ))}
185	                </div>
186	              </div>
187	            )}
188	          </div>
189	        </nav>
190	
191	        <div className="hidden items-center gap-2 lg:flex">
192	          <Link href="/status" className="flex items-center gap-1.5 rounded-full border border-white/[0.07] px-2.5 py-1 text-xs text-slate-400 transition-colors hover:text-white">
193	            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse-dot" />
194	            Status
195	          </Link>
196	          {authed ? (
197	            <>
198	              <Link href="/dashboard/settings" className="btn-ghost">My account</Link>
199	              <Link href="/dashboard" className="btn-primary">Back to portal</Link>
200	            </>
201	          ) : (
202	            <>
203	              <Link href="/login" className="btn-ghost">Log in</Link>
204	              <Link href="/register" className="btn-primary">Get started</Link>
205	            </>
206	          )}
207	        </div>
208	
209	        <button
210	          className="btn-ghost rounded-lg p-2 lg:hidden"
211	          aria-label="Toggle menu"
212	          aria-expanded={open}
213	          onClick={() => setOpen((v) => !v)}
214	        >
215	          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
216	            {open ? <path d="M6 6l12 12M18 6 6 18" /> : <path d="M4 7h16M4 12h16M4 17h16" />}
217	          </svg>
218	        </button>
219	      </div>
220	
221	      {/* Desktop mega-menu panels */}
222	      {menu === "products" && (
223	        <div
224	          className="absolute inset-x-0 top-full hidden lg:block"
225	          onMouseEnter={() => openMenu("products")}
226	          onMouseLeave={scheduleClose}
227	        >
228	          <div className="rail pb-6">
229	            <div className="grid grid-cols-[1.1fr_1.1fr_1.1fr_0.9fr] gap-2 rounded-2xl border border-white/10 bg-navy-950/95 p-3 shadow-2xl backdrop-blur-2xl">
230	              {PRODUCT_GROUPS.map((g) => (
231	                <div key={g.title} className="p-2">
232	                  <p className="section-label mb-2 px-2">{g.title}</p>
233	                  <div className="space-y-0.5">
234	                    {g.items.map((it) => (
235	                      <MegaItem key={it.label} item={it} />
236	                    ))}
237	                  </div>
238	                </div>
239	              ))}
240	              <div className="rounded-xl bg-white/[0.02] p-2">
241	                <p className="section-label mb-2 px-2">By use case</p>
242	                <div className="space-y-0.5">
243	                  {USE_CASES.map((it) => (
244	                    <MegaItem key={it.label} item={it} />
245	                  ))}
246	                </div>
247	                <div className="mx-2 my-2 border-t border-white/[0.06]" />
248	                <Link href="/features" className="flex items-center justify-between rounded-lg px-2 py-2 text-sm text-brand-300 hover:bg-white/[0.04]">
249	                  All features <IconArrow size={15} />
250	                </Link>
251	              </div>
252	            </div>
253	          </div>
254	        </div>
255	      )}
256	
257	      {/* Mobile drawer */}
258	      {open && (
259	        <div className="border-t border-white/[0.06] bg-navy-950/95 backdrop-blur-xl lg:hidden">
260	          <nav className="rail flex max-h-[70vh] flex-col gap-1 overflow-y-auto py-4">
261	            {PRODUCT_GROUPS.map((g) => (
262	              <div key={g.title} className="mb-1">
263	                <p className="section-label px-3 pb-1 pt-2">{g.title}</p>
264	                {g.items.map((it) => (
265	                  <Link key={it.label} href={it.href} className="flex items-center gap-3 rounded-lg px-3 py-2 text-sm text-slate-300 hover:bg-white/[0.05] hover:text-white">
266	                    <span className="text-brand-300">{it.icon({ size: 18 })}</span>
267	                    {it.label}
268	                    {it.badge && <span className="rounded-full bg-brand-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-brand-200">{it.badge}</span>}
269	                  </Link>
270	                ))}
271	              </div>
272	            ))}
273	            <div className="my-1 border-t border-white/[0.06]" />
274	            {[
275	              { label: "Pricing", href: "/pricing" },
276	              { label: "Compare", href: "/compare" },
277	              { label: "NxLabs", href: "/mods", badge: "Game Mod Store" },
278	              ...COMPANY,
279	            ].map((l) => (
280	              <Link key={l.href} href={l.href} className="flex items-center gap-1.5 rounded-lg px-3 py-2.5 text-sm font-medium text-slate-300 hover:bg-white/[0.05] hover:text-white">
281	                {l.label}
282	                {"badge" in l && l.badge && (
283	                  <span className="rounded-full bg-brand-500/20 px-1.5 py-0.5 text-[10px] font-semibold leading-none text-brand-200">{l.badge}</span>
284	                )}
285	              </Link>
286	            ))}
287	            <div className="mt-2 flex flex-col gap-2 border-t border-white/[0.06] pt-3">
288	              {authed ? (
289	                <>
290	                  <Link href="/dashboard/settings" className="btn-secondary w-full">My account</Link>
291	                  <Link href="/dashboard" className="btn-primary w-full">Back to portal</Link>
292	                </>
293	              ) : (
294	                <>
295	                  <Link href="/login" className="btn-secondary w-full">Log in</Link>
296	                  <Link href="/register" className="btn-primary w-full">Get started</Link>
297	                </>
298	              )}
299	            </div>
300	          </nav>
301	        </div>
302	      )}
303	    </header>
304	  );
305	}
306	
307	function TopLink({ href, pathname, badge, children }: { href: string; pathname: string; badge?: string; children: React.ReactNode }) {
308	  const active = pathname === href;
309	  return (
310	    <Link href={href} className={`nav-underline flex items-center gap-1.5 rounded-lg px-3 py-2 text-sm font-medium transition-colors ${active ? "is-open text-white" : "text-slate-400 hover:text-white"}`}>
311	      {children}
312	      {badge && <span className="rounded-full bg-brand-500/20 px-1.5 py-0.5 text-[10px] font-semibold leading-none text-brand-200">{badge}</span>}
313	    </Link>
314	  );
315	}
316	
317	function MegaItem({ item }: { item: Item }) {
318	  return (
319	    <Link href={item.href} className="group flex items-start gap-3 rounded-xl px-2 py-2 transition-colors hover:bg-white/[0.05]">
320	      <span className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border border-white/[0.06] bg-white/[0.03] text-brand-300 transition-colors group-hover:border-brand-500/30 group-hover:text-brand-200">
321	        {item.icon({ size: 17 })}
322	      </span>
323	      <span className="min-w-0">
324	        <span className="flex items-center gap-1.5 text-sm font-medium text-slate-100">
325	          {item.label}
326	          {item.badge && <span className="rounded-full bg-brand-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-brand-200">{item.badge}</span>}
327	        </span>
328	        <span className="block truncate text-xs text-slate-500">{item.desc}</span>
329	      </span>
330	    </Link>
331	  );
332	}
333	
334	function Chevron({ open }: { open: boolean }) {
335	  return (
336	    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" className={`transition-transform duration-200 ${open ? "rotate-180" : ""}`}>
337	      <path d="m6 9 6 6 6-6" />
338	    </svg>
339	  );
340	}
