30	  type ModDetail,
31	} from "@/lib/mods-catalog";
32	
33	export const dynamic = "force-dynamic";
34	
35	type Params = { params: Promise<{ family: string; slug: string }> };
36	
37	export async function generateStaticParams(): Promise<Array<{ family: string; slug: string }>> {
38	  return listCatalogSlugs();
39	}
40	
41	/**
42	 * Real, non-fabricated images for a mod, in preference order: its own icon
43	 * first (the small square logo every card/detail page already leads with),
44	 * then its real gallery screenshots (Modrinth's project `gallery[]`).
45	 * Returns [] for a mod with neither — callers must omit the `image`/`images`
46	 * property entirely rather than pad it with a stand-in, matching this
47	 * catalogue's no-guessing convention (see lib/mods-catalog.ts's file header).
48	 */
49	function realImagesFor(mod: Pick<ModDetail, "iconUrl" | "galleryUrls">): string[] {
50	  return [mod.iconUrl, ...mod.galleryUrls].filter((url): url is string => !!url);
51	}
52	
53	/**
54	 * A proper ~150-160 char meta description, preferring the real
55	 * `longDescription` (Modrinth's own project body, backfilled by
56	 * scripts/backfill-modrinth-descriptions.ts) over the short `description`
57	 * tagline when it's available — the short tagline is often thin, one line,
58	 * or (pre-backfill) literally missing, while the source's own longer body is
59	 * real prose that reads better truncated to meta-description length. Falls
60	 * back to `description`, then to a description built entirely from other
61	 * real fields (name/family/source) — never fabricated copy.
62	 */
63	function metaDescriptionFor(mod: Pick<ModDetail, "name" | "gameFamilyLabel" | "source" | "description" | "longDescription">): string {
64	  const raw = mod.longDescription?.trim() || mod.description?.trim() || "";
65	  if (raw) {
66	    // longDescription is raw Markdown — strip the common markup so a meta
67	    // tag doesn't read "## Features\n- ..." verbatim, then collapse
68	    // whitespace/newlines into a single line before truncating.
69	    const plain = raw
70	      .replace(/```[\s\S]*?```/g, " ")
71	      .replace(/!\[[^\]]*\]\([^)]*\)/g, " ")
72	      .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
73	      .replace(/[#>*_`~-]/g, " ")
74	      .replace(/\s+/g, " ")
75	      .trim();
76	    if (plain.length <= 160) return plain;
77	    const cut = plain.slice(0, 157);
78	    const lastSpace = cut.lastIndexOf(" ");
79	    return `${cut.slice(0, lastSpace > 100 ? lastSpace : 157)}…`;
80	  }
81	  return `${mod.name} for ${mod.gameFamilyLabel}, verified against ${SOURCE_LABEL[mod.source] ?? mod.source} — real download counts, supported versions, and a direct download link.`;
82	}
83	
84	export async function generateMetadata({ params }: Params): Promise<Metadata> {
85	  const { family, slug } = await params;
86	  const mod = await getCatalogMod(family, slug);
87	  if (!mod) return { title: "Mod not found" };
