"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

/**
 * Context-aware "back" link for a mod detail page (item 3 of the NxLabs
 * overhaul brief). No `?from=` query-param convention exists anywhere else
 * in this codebase (checked before building this — grepped for
 * `document.referrer`, `router.back()`, and any existing back-button
 * component; none of the three), so this reads the real browser
 * `document.referrer` instead: when a visitor arrived from this mod's own
 * game-family page (marketing `/mods/games/[family]` or the portal
 * equivalent), the link returns them there; otherwise (search engine, a
 * shared direct link, coming from search on the homepage, or referrer
 * unavailable at all — e.g. Safari ITP strips it) it falls back to the
 * NxLabs home.
 *
 * `document.referrer` doesn't exist during SSR, so the initial render always
 * matches the server-rendered fallback (no hydration mismatch) and this only
 * ever upgrades post-mount, in a `useEffect`.
 */
export function ModBackLink({
  gameFamilyHref,
  gameFamilyLabel,
  fallbackHref,
  fallbackLabel,
  className,
}: {
  gameFamilyHref: string;
  gameFamilyLabel: string;
  fallbackHref: string;
  fallbackLabel: string;
  className?: string;
}) {
  const [target, setTarget] = useState<{ href: string; label: string }>({ href: fallbackHref, label: fallbackLabel });

  useEffect(() => {
    try {
      const ref = document.referrer;
      if (!ref) return;
      const refUrl = new URL(ref);
      if (refUrl.origin !== window.location.origin) return;
      const refPath = refUrl.pathname.replace(/\/+$/, "");
      const gamePath = gameFamilyHref.replace(/\/+$/, "");
      if (refPath === gamePath) {
        setTarget({ href: gameFamilyHref, label: gameFamilyLabel });
      }
    } catch {
      // Malformed or unparsable referrer — keep the fallback target.
    }
  }, [gameFamilyHref, gameFamilyLabel]);

  return (
    <Link
      href={target.href}
      className={
        className ??
        "inline-flex items-center gap-1.5 text-sm font-medium text-brand-300 transition-colors hover:text-brand-200"
      }
    >
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
        <path d="m15 18-6-6 6-6" />
      </svg>
      Back to {target.label}
    </Link>
  );
}

