1	/**
2	 * Backfill `GameMod.longDescription` for existing Modrinth rows — the real
3	 * quick win identified investigating NxLabs's thin-description complaint
4	 * (2026-09-20 owner screenshot review: CounterStrikeSharp's description was
5	 * just GitHub's one-line repo `description`, "C# plugin runtime most CS2
6	 * plugins need.").
7	 *
8	 * PER-SOURCE INVESTIGATION (what this script does and does not fix):
9	 *
10	 *   - Modrinth: a real DB check (scripts/_tmp-check-descriptions.ts, run
11	 *     2026-09-20, then deleted) found 0 null/empty descriptions catalogue-wide
12	 *     but every source's `description` is a short one-liner (avg 42-84
13	 *     chars) — that field is Modrinth's own search-hit `description` (a
14	 *     tagline), never its `body` field (the project's actual page content —
15	 *     confirmed live: `GET /v2/project/sodium` returns a `body` of 5,594
16	 *     characters of real markdown, completely separate from its 124-char
17	 *     `description`). scripts/import-modrinth-catalog.ts's own `FullProject`
18	 *     type (used for its bulk `/v2/projects?ids=[...]` call) simply never
19	 *     read `body` off the response it already had in hand. THIS script fixes
20	 *     that gap for existing rows without touching the import script itself
21	 *     (per this task's "concurrent import pipeline work in progress"
22	 *     constraint) — it makes the SAME bulk `/v2/projects?ids=[...]` call
23	 *     (which also carries `body`, confirmed live) over already-imported
24	 *     modrinth rows and writes the real result into the new
25	 *     `longDescription` column. Nothing is fabricated: a project whose body
26	 *     is empty gets left null, not padded.
27	 *
28	 *   - GitHub: NOT touched by this script. A repo's `description` field IS
29	 *     the whole of what GitHub's repo metadata offers for a one-liner — there
30	 *     is no hidden longer field the way Modrinth has `body`. The closest real
31	 *     "richer, already-public" text is a repo's README
32	 *     (`GET /repos/{o}/{r}/readme`), which is a genuinely different fetch
33	 *     (a different API, different rate limit, needs its own markdown-vs-HTML
34	 *     handling) layered on top of the GitHub import pipeline another agent is
35	 *     actively building right now (scripts/import-github-catalog.ts) — adding
36	 *     it here would mean editing that in-progress file. Left as a note for
37	 *     whoever owns that pipeline next, not implemented in this pass.
38	 *
39	 *   - Thunderstore / uMod / SpigotMC / Nexus / Codefling: not investigated in
40	 *     this pass (12 rows total across all four, sourceId formats and APIs
41	 *     all differ) — Modrinth alone is 32,243 of the catalogue's 32,331 active
42	 *     rows (99.7%), so it is where a backfill actually moves the needle.
43	 *
44	 * IDEMPOTENT: only touches rows where `longDescription IS NULL` by default
45	 * (safe to re-run — it converges rather than re-fetching the same rows
46	 * forever); pass --refresh to also re-fetch rows that already have one (e.g.
47	 * after a project has updated its page).
48	 *
49	 * SAFETY: this is a bulk-WRITE script, so it goes through the same
50	 * NXEON_DB_TARGET confirmation as every other writing script in this repo
51	 * (scripts/db-target-guard.ts) and defaults to a dry run.
52	 *
53	 *   Dry run (no writes), tiny slice:
54	 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/backfill-modrinth-descriptions.ts --limit=50
55	 *
56	 *   Real write, tiny slice:
57	 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/backfill-modrinth-descriptions.ts --limit=50 --apply
58	 *
59	 *   Full real run:
60	 *     NXEON_DB_TARGET=nxeon npx tsx scripts/backfill-modrinth-descriptions.ts --apply
61	 */
62	
63	import { assertDbTarget } from "./db-target-guard";
64	assertDbTarget("backfill-modrinth-descriptions.ts");
65	
66	import { db } from "../lib/db";
67	
68	const UA = "Nxeon/1.0 (mods@nxeon.cloud)";
69	const MODRINTH_KEY = process.env.MODRINTH_API_KEY ?? "";
70	const API = "https://api.modrinth.com/v2";
71	const BATCH_SIZE = 100; // Modrinth's real cap on /projects?ids=[...]
72	const RATE_LIMIT_PER_MIN = 280; // stay under Modrinth's real 300/min, matches import-modrinth-catalog.ts
73	
74	function parseArgs(argv: string[]) {
75	  const get = (name: string) => argv.find((a) => a.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
76	  return {
77	    apply: argv.includes("--apply"),
78	    refresh: argv.includes("--refresh"),
79	    limit: get("limit") ? Number(get("limit")) : undefined,
80	  };
81	}
82	
83	class RateLimiter {
84	  private minIntervalMs: number;
85	  private last = 0;
86	  constructor(perMin: number) {
87	    this.minIntervalMs = 60_000 / perMin;
88	  }
89	  async wait() {
90	    const elapsed = Date.now() - this.last;
91	    if (elapsed < this.minIntervalMs) await new Promise((r) => setTimeout(r, this.minIntervalMs - elapsed));
92	    this.last = Date.now();
93	  }
94	}
95	
96	async function apiFetch(limiter: RateLimiter, url: string, attempt = 1): Promise<Response> {
97	  await limiter.wait();
98	  const headers: Record<string, string> = { "User-Agent": UA };
99	  if (MODRINTH_KEY) headers.Authorization = MODRINTH_KEY;
100	  const res = await fetch(url, { headers });
101	  if (res.status === 429 && attempt <= 6) {
102	    const retryAfterMs = Number(res.headers.get("retry-after") ?? 0) * 1000;
103	    const backoffMs = Math.max(retryAfterMs, 1000 * 2 ** attempt);
104	    console.warn(`  [rate-limit] 429 — backing off ${Math.round(backoffMs / 1000)}s (attempt ${attempt})`);
105	    await new Promise((r) => setTimeout(r, backoffMs));
106	    return apiFetch(limiter, url, attempt + 1);
107	  }
108	  if (res.status >= 500 && attempt <= 4) {
109	    const backoffMs = 1000 * 2 ** attempt;
110	    console.warn(`  [server-error] ${res.status} — retrying in ${Math.round(backoffMs / 1000)}s`);
111	    await new Promise((r) => setTimeout(r, backoffMs));
112	    return apiFetch(limiter, url, attempt + 1);
113	  }
114	  return res;
115	}
116	
117	type FullProject = { id: string; slug: string; body?: string | null };
118	
119	async function main() {
120	  const args = parseArgs(process.argv.slice(2));
121	  const limiter = new RateLimiter(RATE_LIMIT_PER_MIN);
122	
123	  const rows = await db.gameMod.findMany({
124	    where: {
125	      source: "modrinth",
126	      sourceId: { not: null },
127	      ...(args.refresh ? {} : { longDescription: null }),
128	    },
129	    select: { id: true, sourceId: true, name: true },
130	    ...(args.limit ? { take: args.limit } : {}),
131	  });
132	
133	  console.log(
134	    `[backfill-modrinth-descriptions] ${rows.length} row(s) to check` +
135	      (args.refresh ? " (--refresh: including rows that already have one)" : " (rows with longDescription IS NULL)") +
136	      (args.apply ? " — APPLY mode" : " — DRY RUN, no writes")
137	  );
138	  if (rows.length === 0) {
139	    await db.$disconnect();
140	    return;
141	  }
142	
143	  const bySlug = new Map(rows.map((r) => [r.sourceId!, r]));
144	  const slugs = [...bySlug.keys()];
145	
146	  let checked = 0;
147	  let filled = 0;
148	  let emptyBody = 0;
149	  let missingFromApi = 0;
150	  let failed = 0;
151	
152	  for (let i = 0; i < slugs.length; i += BATCH_SIZE) {
153	    const batch = slugs.slice(i, i + BATCH_SIZE);
154	    const idsParam = encodeURIComponent(JSON.stringify(batch));
155	    const res = await apiFetch(limiter, `${API}/projects?ids=${idsParam}`);
156	    if (!res.ok) {
157	      console.error(`  [batch ${i / BATCH_SIZE + 1}] HTTP ${res.status} — skipping this batch of ${batch.length}`);
158	      failed += batch.length;
159	      continue;
160	    }
161	    const projects: FullProject[] = await res.json();
162	    // Modrinth's bulk endpoint accepts either real ids or slugs and echoes
163	    // back whichever the project's canonical `slug` is today, which does not
164	    // always match what we stored (renames happen) — index by BOTH id and
165	    // slug from the response, then fall back to matching in requested order
166	    // for any that still don't line up.
167	    const byIdOrSlug = new Map<string, FullProject>();
168	    for (const p of projects) {
169	      byIdOrSlug.set(p.id, p);
170	      byIdOrSlug.set(p.slug, p);
171	    }
172	
173	    for (const requestedSlug of batch) {
174	      checked++;
175	      const row = bySlug.get(requestedSlug)!;
176	      const proj = byIdOrSlug.get(requestedSlug);
177	      if (!proj) {
178	        missingFromApi++;
179	        continue;
180	      }
181	      const body = (proj.body ?? "").trim();
182	      if (!body) {
183	        emptyBody++;
184	        continue;
185	      }
186	      filled++;
187	      if (args.apply) {
188	        try {
189	          await db.gameMod.update({ where: { id: row.id }, data: { longDescription: body } });
190	        } catch (e) {
191	          failed++;
192	          filled--;
193	          const msg = e instanceof Error ? e.message : String(e);
194	          console.error(`  [db] failed to update ${row.name} (${requestedSlug}): ${msg}`);
195	        }
196	      }
197	    }
198	
199	    console.log(
200	      `  [batch ${Math.floor(i / BATCH_SIZE) + 1}/${Math.ceil(slugs.length / BATCH_SIZE)}] ` +
201	        `checked=${checked} filled=${filled} empty_body=${emptyBody} missing=${missingFromApi} failed=${failed}`
202	    );
203	  }
204	
205	  console.log(
206	    `\n[backfill-modrinth-descriptions] done. checked=${checked} ${args.apply ? "filled" : "would_fill"}=${filled} ` +
207	      `empty_body=${emptyBody} missing_from_api=${missingFromApi} failed=${failed}`
208	  );
209	  if (!args.apply) console.log("Dry run only — re-run with --apply to write.");
210	
211	  await db.$disconnect();
212	}
213	
214	main().catch((e) => {
215	  console.error(e);
216	  process.exit(1);
217	});
