import type { Metadata } from "next";
import Link from "next/link";
import { Eyebrow, Section, SectionTitle } from "@/components/marketing/primitives";
import { GameParticleField } from "@/components/marketing/showcase/GameParticleField";
import { StoreBrowser, type SortKey } from "@/components/mods/StoreBrowser";
import { GameCatalogueGrid } from "@/components/mods/GameCatalogueGrid";
