"use client";

import { useRef } from "react";
import type { ModSummary } from "@/lib/mods-catalog";
import { ModCard } from "./ModCard";
import { IconArrow } from "./icons";

/**
 * A curated mod rail rendered as a real sliding carousel — item 6 of the
 * 2026-09-20 NxLabs overhaul. Reuses the exact scroll-snap-track +
 * arrow-button + pointer-drag mechanism GameCatalogueCarousel.tsx already
 * shipped tonight for the game catalogue (this codebase's only other
 * carousel — checked before writing a second one), just swapping its
 * game-poster tile for a full ModCard. No search box here: unlike the ~17
 * game families search made sense over, a single curated rail is only
 * 8-12 mods, and the real "see everything" escape hatch is the "View more"
 * link its caller renders next to the section heading, into the full
 * searchable/paginated StoreBrowser grid scoped to the same sort.
 *
 * `mods` is plain, already-serializable data (ModSummary — dates as ISO
 * strings), so unlike GameCatalogueGrid/Carousel's server/client split this
 * needs no separate Server Component wrapper; a page just passes its
 * already-fetched rows straight in.
 */
function prefersReducedMotion() {
  return typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
}

export function ModCarouselRow({
  mods,
  hrefFor,
  showGameBadge = false,
  showCategoryLabel = true,
}: {
  mods: ModSummary[];
  hrefFor: (mod: ModSummary) => string;
  showGameBadge?: boolean;
  showCategoryLabel?: boolean;
}) {
  const trackRef = useRef<HTMLDivElement>(null);

  function scrollByCard(dir: 1 | -1) {
    const track = trackRef.current;
    if (!track) return;
    const card = track.querySelector<HTMLElement>("[data-card]");
    const step = card ? card.offsetWidth + 20 /* gap-5 */ : track.clientWidth * 0.8;
    track.scrollBy({ left: dir * step, behavior: prefersReducedMotion() ? "auto" : "smooth" });
  }

  // Same desktop-mouse drag-to-scroll as GameCatalogueCarousel — touch/
  // trackpad already get real native scrolling from scroll-snap with no JS.
  const drag = useRef<{ startX: number; startScroll: number; moved: boolean } | null>(null);
  function onPointerDown(e: React.PointerEvent<HTMLDivElement>) {
    if (e.pointerType === "touch") return;
    const track = trackRef.current;
    if (!track) return;
    drag.current = { startX: e.clientX, startScroll: track.scrollLeft, moved: false };
    track.setPointerCapture(e.pointerId);
  }
  function onPointerMove(e: React.PointerEvent<HTMLDivElement>) {
    const st = drag.current;
    const track = trackRef.current;
    if (!st || !track) return;
    const dx = e.clientX - st.startX;
    if (Math.abs(dx) > 3) st.moved = true;
    track.scrollLeft = st.startScroll - dx;
  }
  function onPointerUp(e: React.PointerEvent<HTMLDivElement>) {
    const st = drag.current;
    const track = trackRef.current;
    if (st?.moved && track) {
      const stop = (ev: Event) => {
        ev.preventDefault();
        ev.stopPropagation();
      };
      track.addEventListener("click", stop, { capture: true, once: true });
    }
    drag.current = null;
    track?.releasePointerCapture?.(e.pointerId);
  }

  if (mods.length === 0) return null;

  return (
    <div className="relative">
      <div className="pointer-events-none absolute inset-y-0 left-0 right-0 z-20 hidden items-center justify-between sm:flex">
        <button
          type="button"
          aria-label="Scroll mods left"
          onClick={() => scrollByCard(-1)}
          className="pointer-events-auto -ml-3 grid h-10 w-10 place-items-center rounded-full border border-white/10 bg-navy-900/80 text-slate-200 backdrop-blur transition hover:border-brand-500/40 hover:text-white lg:-ml-5"
        >
          <span className="rotate-180">
            <IconArrow size={18} />
          </span>
        </button>
        <button
          type="button"
          aria-label="Scroll mods right"
          onClick={() => scrollByCard(1)}
          className="pointer-events-auto -mr-3 grid h-10 w-10 place-items-center rounded-full border border-white/10 bg-navy-900/80 text-slate-200 backdrop-blur transition hover:border-brand-500/40 hover:text-white lg:-mr-5"
        >
          <IconArrow size={18} />
        </button>
      </div>

      <div
        ref={trackRef}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        className="flex snap-x snap-mandatory gap-5 overflow-x-auto scroll-smooth pb-4 pt-1 [scrollbar-width:none] motion-reduce:scroll-auto [&::-webkit-scrollbar]:hidden"
        style={{ cursor: "grab" }}
      >
        {mods.map((mod) => (
          <div key={mod.id} data-card className="w-64 shrink-0 snap-start sm:w-72">
            <ModCard mod={mod} href={hrefFor(mod)} showGameBadge={showGameBadge} showCategoryLabel={showCategoryLabel} />
          </div>
        ))}
      </div>
    </div>
  );
}

