9	
10	export const dynamic = "force-dynamic";
11	
12	const VALID_SORTS = new Set<SortKey>(["featured", "downloads", "latest", "rating"]);
13	function parseSort(v?: string): SortKey {
14	  return v && VALID_SORTS.has(v as SortKey) ? (v as SortKey) : "featured";
15	}
16	
17	/**
18	 * NxLabs, inside the portal — the SAME catalog as the public /mods pages
19	 * (lib/mods-catalog.ts), with one addition a logged-in customer gets for
20	 * free: a real, matching server can be added to in one click, right from the
21	 * grid. Nothing here forks the install path — QuickAddButton calls the same
22	 * installMod() server action as the per-server Mods tab (ModsPanel.tsx) and
23	 * the public detail page's AddToServerWidget.
24	 *
25	 * Portal/marketing split: this page and everything under app/dashboard/nxlabs/**
26	 * render through the Nexion portal shell (app/dashboard/layout.tsx ->
27	 * components/nx/Shell.tsx) automatically by living under /dashboard — the
28	 * fix for the old bug where a portal mod card linked out to the PUBLIC
29	 * /mods/[family]/[slug] route is simply that every href below points at this
30	 * tree's own /dashboard/nxlabs/... routes instead.
31	 */
32	type Search = { q?: string; sort?: string; page?: string };
33	
34	export default async function NxLabsPage({ searchParams }: { searchParams: Promise<Search> }) {
35	  const user = await requireUser();
36	  const sp = await searchParams;
37	  const q = (sp.q ?? "").trim();
38	  const sort = parseSort(sp.sort);
39	  const page = Number(sp.page) || 1;
40	
41	  const [families, result, totalDownloads, myServers] = await Promise.all([
42	    listCatalogFamilies(),
43	    queryCatalogMods({ q, sort, page }),
44	    totalDownloadsFor(),
45	    db.server.findMany({
46	      where: { userId: user.id, status: { notIn: ["DELETING"] } },
47	      include: { osTemplate: true, gamePlan: true },
48	    }),
49	  ]);
50	  const { mods, total, totalPages, perPage, page: resolvedPage } = result;
51	
52	  // One pass over the (small) server list per mod family, so the grid below
53	  // does zero extra queries — matches getEligibleServersForMod's own rules
54	  // (family + variant) but computed once for everyone on the page. Plain
55	  // object, not a Map — this is handed to a Client Component as a prop and
56	  // has to be JSON-serializable.
57	  const serversByFamily: Record<string, QuickAddServer[]> = {};
58	  for (const s of myServers) {
59	    const fam = familyFor(s);
60	    if (!fam) continue;
61	    (serversByFamily[fam] ??= []).push({ id: s.id, hostname: s.hostname, label: s.label });
62	  }
63	
64	  const totalMods = families.reduce((sum, f) => sum + f.count, 0);
65	  // Real dedicated /dashboard/nxlabs/games/[family] pages, not an in-page
66	  // re-filter of this page's own (much smaller) loaded array — see the
67	  // marketing cross-game page's identical comment for why.
68	  const chips = families.map((f) => ({ key: f.family, label: f.label, count: f.count, href: `/dashboard/nxlabs/games/${f.family}` }));
69	
70	  return (
71	    <PageShell
72	      eyebrow="NxLabs"
73	      title="Mods & plugins"
74	      sub={`Browse the same verified catalog anyone can — with one-click install for the ${myServers.length ? "servers" : "server"} you own.`}
75	      tagline={["VERIFIED SOURCES.", "ONE-CLICK INSTALL."]}
76	      heroImage="/nxlabs/hero-collage.png"
77	    >
78	      <div className="mb-6 flex flex-wrap items-center gap-6 text-sm text-tx-mute">
79	        <span>
80	          <strong className="text-white">{totalMods}</strong> mods &amp; plugins
81	        </span>
82	        <span>
83	          <strong className="text-white">{families.length}</strong> games supported
84	        </span>
85	        {totalDownloads > 0 && (
86	          <span>
87	            <strong className="text-white">{formatDownloads(totalDownloads)}</strong> total downloads
88	          </span>
89	        )}
90	      </div>
91	
92	      <div className="mb-8">
93	        <h2 className="mb-3 text-sm font-semibold uppercase tracking-wide text-tx-mute">Browse by game</h2>
94	        <GameCatalogueGrid families={families} hrefFor={(family) => `/dashboard/nxlabs/games/${family}`} />
95	      </div>
96	
97	      <StoreBrowser
98	        mods={mods}
99	        total={total}
100	        page={resolvedPage}
101	        totalPages={totalPages}
102	        perPage={perPage}
103	        chips={chips}
104	        chipField="gameFamily"
105	        basePath="/dashboard/nxlabs"
106	        q={q}
107	        sort={sort}
108	        showGameBadge
109	        serversByFamily={serversByFamily}
110	        deployHref="/dashboard/deploy"
111	      />
112	    </PageShell>
113	  );
114	}
