import Link from "next/link";

/**
 * Portal-flavored curated-row header (title + "View more" on the right) —
 * item 6 of the 2026-09-20 NxLabs overhaul, shared by both
 * app/dashboard/nxlabs/page.tsx and app/dashboard/nxlabs/games/[family]/
 * page.tsx. Same layout as marketing's RowHeader
 * (components/marketing/primitives.tsx) but built with the portal's OWN
 * color tokens (text-white/text-tx-mute/text-tx-faint) instead of the
 * marketing theme's `--fg`/`--fg-muted` CSS vars, which are never defined
 * inside the Nexion portal shell's own scoped theme (see app/globals.css's
 * `@theme` comment on why the two token sets stay separate) — reusing the
 * marketing component as-is here would have silently rendered with the
 * wrong (or undefined) colors.
 */
export function PortalRowHeader({
  eyebrow,
  title,
  sub,
  viewMoreHref,
}: {
