24	 * imports into the browser bundle and broke the production build entirely.
25	 * Fixed the correct way: this component only owns the carousel SHELL
26	 * (scroll-snap track, arrows, drag-to-scroll); the caller (a Server
27	 * Component page) renders each `<ModCard>` itself and hands the already-
28	 * rendered elements in via `items`, exactly the split GameCatalogueGrid/
29	 * Carousel already used for the same reason.
30	 */
31	function prefersReducedMotion() {
32	  return typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
33	}
34	
35	export function ModCarouselRow({
36	  items,
37	}: {
38	  items: { key: string; node: React.ReactNode }[];
39	}) {
40	  const trackRef = useRef<HTMLDivElement>(null);
41	
42	  function scrollByCard(dir: 1 | -1) {
43	    const track = trackRef.current;
44	    if (!track) return;
45	    const card = track.querySelector<HTMLElement>("[data-card]");
46	    const step = card ? card.offsetWidth + 20 /* gap-5 */ : track.clientWidth * 0.8;
47	    track.scrollBy({ left: dir * step, behavior: prefersReducedMotion() ? "auto" : "smooth" });
48	  }
49	
50	  // Same desktop-mouse drag-to-scroll as GameCatalogueCarousel — touch/
51	  // trackpad already get real native scrolling from scroll-snap with no JS.
52	  const drag = useRef<{ startX: number; startScroll: number; moved: boolean } | null>(null);
53	  function onPointerDown(e: React.PointerEvent<HTMLDivElement>) {
54	    if (e.pointerType === "touch") return;
55	    const track = trackRef.current;
56	    if (!track) return;
57	    drag.current = { startX: e.clientX, startScroll: track.scrollLeft, moved: false };
58	    track.setPointerCapture(e.pointerId);
59	  }
60	  function onPointerMove(e: React.PointerEvent<HTMLDivElement>) {
61	    const st = drag.current;
62	    const track = trackRef.current;
63	    if (!st || !track) return;
64	    const dx = e.clientX - st.startX;
65	    if (Math.abs(dx) > 3) st.moved = true;
66	    track.scrollLeft = st.startScroll - dx;
67	  }
68	  function onPointerUp(e: React.PointerEvent<HTMLDivElement>) {
69	    const st = drag.current;
70	    const track = trackRef.current;
71	    if (st?.moved && track) {
72	      const stop = (ev: Event) => {
73	        ev.preventDefault();
74	        ev.stopPropagation();
75	      };
76	      track.addEventListener("click", stop, { capture: true, once: true });
77	    }
78	    drag.current = null;
79	    track?.releasePointerCapture?.(e.pointerId);
80	  }
81	
82	  if (mods.length === 0) return null;
83	
84	  return (
85	    <div className="relative">
86	      <div className="pointer-events-none absolute inset-y-0 left-0 right-0 z-20 hidden items-center justify-between sm:flex">
87	        <button
88	          type="button"
89	          aria-label="Scroll mods left"
90	          onClick={() => scrollByCard(-1)}
91	          className="pointer-events-auto -ml-3 grid h-10 w-10 place-items-center rounded-full border border-white/10 bg-navy-900/80 text-slate-200 backdrop-blur transition hover:border-brand-500/40 hover:text-white lg:-ml-5"
92	        >
93	          <span className="rotate-180">
94	            <IconArrow size={18} />
95	          </span>
96	        </button>
97	        <button
